examples.template:
MonarchAiWelcome(
    {{title}},
    agent: MonarchAiAgentRef(name: {{agent.name}}, role: {{agent.role}}),
    description: {{description}},
    starters: {
        MonarchAiStarterPrompts(
            [
                MonarchAiStarterPrompt(id: {{prompts.0.id}}, title: {{prompts.0.title}}, prompt: {{prompts.0.prompt}}),
                MonarchAiStarterPrompt(id: {{prompts.1.id}}, title: {{prompts.1.title}}, prompt: {{prompts.1.prompt}}),
            ]
        ) { starter in
            draft = starter.prompt
        }
    }
)

examples.code:
MonarchAiWelcome(
    "How can I help?",
    agent: MonarchAiAgentRef(name: "Assistant", role: "Workspace assistant"),
    description: "I can read the page you are on and the documents you share with me.",
    starters: {
        MonarchAiStarterPrompts(
            [
                MonarchAiStarterPrompt(id: "sum", title: "Summarise this page", prompt: "Summarise this page."),
                MonarchAiStarterPrompt(id: "next", title: "Suggest next steps", prompt: "What should I do next on this project?"),
            ]
        ) { starter in
            draft = starter.prompt
        }
    }
)
